/* ================= Bristol ================= */
br_eye: ["Real leaks · Bristol, UK", "تسربات حقيقية · بريستول، بريطانيا"], br_h1: ["Four real leaks. One question: where?", "أربعة تسربات حقيقية. وسؤال واحد: أين؟"],
br_lead: ["On 12 and 13 June 2024 researchers opened four hydrants on a real 63 km network with 40 pressure loggers and let water out at 1, 3 and 5 L/s. We gave the locator the time of each leak and the logger readings. The code was frozen before the run and ran once. The leak time was given, so this tests locating, not detecting.",
          "في 12 و13 يونيو 2024 فتح باحثون أربعة صنابير حريق على شبكة حقيقية طولها 63 كم فيها 40 مسجّل ضغط، وأخرجوا الماء بمعدل 1 و3 و5 لتر/ث. أعطينا أداة تحديد الموقع وقت كل تسرب وقراءات المسجّلات. جُمّد البرنامج قبل التشغيل وشُغّل مرة واحدة. وقت التسرب كان معطًى، فهذا اختبار لتحديد الموقع لا للكشف."],
br_k: [["trial stages placed within 300 m of the real leak, along the pipes", "of the time, for a random junction", "median distance from the real leak; a random junction: {m} m", "the smallest size: here the tool is at chance"],
       ["مرحلة تجربة حُدّد موقعها ضمن 300 م من التسرب الحقيقي على طول الأنابيب", "من المرات، لتقاطع عشوائي", "وسيط المسافة من التسرب الحقيقي؛ وتقاطع عشوائي: {m} م", "أصغر حجم: هنا الأداة بمستوى الصدفة"]],
br_leak: ["Leak {k}", "التسرب {k}"], br_view: ["View", "العرض"], br_zoom: ["Around the leak", "حول التسرب"], br_all: ["Whole network", "الشبكة كلها"],
br_title: ["Leak {k} at {l} L/s", "التسرب {k} عند {l} لتر/ث"], br_when: ["{d} · a hydrant opened for about 50 minutes · {q} m³/h", "{d} · فُتح صنبور حريق نحو 50 دقيقة · {q} م³/س"],
br_hit: ["Within 300 m", "ضمن 300 م"], br_miss: ["Missed", "أخطأ"],
br_q1: ["Where Guardian placed it", "أين وضعه حارس الشبكة"], br_err: ["{m} m from the real leak, along the pipes.", "{m} م من التسرب الحقيقي على طول الأنابيب."],
br_rand: ["A random junction: {m} m (median), and within 300 m only {p}% of the time.", "تقاطع عشوائي: {m} م (الوسيط)، وضمن 300 م في {p}% فقط من المرات."],
br_rank: ["The real hydrant ranked {r} of {n} junctions in Guardian's list.", "جاء الصنبور الحقيقي في المرتبة {r} من {n} تقاطعًا في قائمة حارس الشبكة."],
br_q2: ["What the loggers felt", "ماذا أحسّت المسجّلات"], br_logs: ["Pressure during the leak minus just before and after, at the six loggers that moved most against their own noise. Orange: a clear drop.", "الضغط أثناء التسرب ناقص ما قبله وما بعده مباشرة، عند المسجّلات الستة الأكثر تحركًا قياسًا بضجيجها. البرتقالي: انخفاض واضح."],
br_q3: ["How to read this", "كيف تقرأ هذا"],
br_read_hit: ["The placed point (orange) is inside the dashed 300 m circle around the real hydrant (violet).", "النقطة الموضوعة (برتقالية) داخل دائرة 300 م المتقطعة حول الصنبور الحقيقي (بنفسجي)."],
br_read_miss: ["The placed point is outside the 300 m circle. At 1 L/s the pressure change is close to the loggers' noise, and the tool does no better than chance.", "النقطة الموضوعة خارج دائرة 300 م. عند 1 لتر/ث يقارب تغيّر الضغط ضجيج المسجّلات، والأداة ليست أفضل من الصدفة."],
br_size: ["Size it estimated: {s} L/s.", "الحجم الذي قدّرته: {s} لتر/ث."],
br_leg: [["where the leak really was", "where Guardian placed it", "its 20 best candidates", "logger: pressure dropped", "logger: no clear change"], ["موقع التسرب الحقيقي", "أين وضعه حارس الشبكة", "أفضل 20 مرشحًا لديه", "مسجّل: انخفض الضغط", "مسجّل: لا تغيّر واضح"]],
br_foot: ["A display of one frozen test (approved claim 17); nothing is computed on this page. Limits: four leaks; the eleven stages are not independent; the hydrant positions were fitted from a figure in the authors' thesis and are not confirmed by them; the settings were tuned on two other leaks the day before; this is the known-time locator, not the year-round detector. Network, loggers and leak trials: Liu, Pecci and Stoianov, Imperial College London, Zenodo 16737160, CC BY 4.0.",
          "عرض لاختبار مجمَّد واحد (الرقم المعتمد 17)؛ لا شيء يُحسب في هذه الصفحة. الحدود: أربعة تسربات؛ والمراحل الإحدى عشرة ليست مستقلة؛ ومواقع الصنابير استُخرجت بمطابقة شكل في أطروحة المؤلفين ولم يؤكدوها؛ وضُبطت الإعدادات على تسربين آخرين في اليوم السابق؛ وهذه أداة تحديد الموقع حين يكون الوقت معلومًا، لا الكاشف الدائم. الشبكة والمسجّلات وتجارب التسرب: Liu, Pecci and Stoianov، إمبريال كوليدج لندن، Zenodo 16737160، CC BY 4.0."],

